package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"testing"
	"time"
)

// TestServedIndex pins the served-read index's contract: touch/recent obey
// the window boundary exactly (within → anchored, past → expired, other
// nonce → never), recentItems projects (item, nonce) reads onto item ids
// dropping window-expired ones, and the past-cap touch prunes only the
// over-age entries — fresh ones survive the prune untouched. Backdating
// rides the map directly (same package): touch always stamps now.
func TestServedIndex(t *testing.T) {
	idx := newServedIndex()
	idx.touch("itm_a", "n1")
	if !idx.recent("itm_a", "n1", time.Minute) {
		t.Fatal("a just-touched read is not recent within a minute")
	}
	if idx.recent("itm_a", "n1", 0) {
		t.Fatal("recent(window 0) answered true for a fresh entry — the window boundary is not exact")
	}
	if idx.recent("itm_a", "n2", time.Minute) {
		t.Fatal("a different nonce answered recent for itm_a's touch")
	}
	if idx.recent("itm_z", "n1", time.Minute) {
		t.Fatal("an item never touched answered recent")
	}

	// Item projection: fresh reads surface their item, stale ones do not.
	idx.touch("itm_b", "n1")
	idx.mu.Lock()
	idx.hits[servedHit{item: "itm_stale", nonce: "n1"}] = time.Now().Add(-2 * playingWindow)
	idx.mu.Unlock()
	got := idx.recentItems(playingWindow)
	if !got["itm_a"] || !got["itm_b"] {
		t.Fatalf("recentItems = %v, want itm_a and itm_b projected", got)
	}
	if got["itm_stale"] {
		t.Fatalf("recentItems = %v, want the window-expired item dropped", got)
	}

	// Prune-at-cap: the over-age entry dies at the crossing touch, fresh
	// entries (count > cap) all survive.
	capIdx := newServedIndex()
	for i := 0; i < servedCap; i++ {
		capIdx.touch(fmt.Sprintf("itm_%d", i), "n")
	}
	capIdx.mu.Lock()
	capIdx.hits[servedHit{item: "itm_dead", nonce: "n"}] = time.Now().Add(-25 * time.Hour)
	capIdx.mu.Unlock()
	capIdx.touch("itm_crossing", "n")
	capIdx.mu.Lock()
	_, deadLeft := capIdx.hits[servedHit{item: "itm_dead", nonce: "n"}]
	if len(capIdx.hits) < servedCap {
		t.Fatalf("prune dropped fresh entries: %d left, want > %d", len(capIdx.hits), servedCap)
	}
	capIdx.mu.Unlock()
	if deadLeft {
		t.Fatal("the over-age entry survived a past-cap prune")
	}
}

// TestServedMediaTouch pins the servedMedia wrapper: a GET or HEAD under
// /media/<item>/<nonce>/… touches the index BEFORE delegation (even for a
// path the underlying handler would 404), tail-segment subpaths touch the
// same (item, nonce), /original never touches, and a non-/media path
// passes through with no index effect.
func TestServedMediaTouch(t *testing.T) {
	idx := newServedIndex()
	passed := make([]string, 0)
	next := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		passed = append(passed, r.URL.Path)
		w.WriteHeader(http.StatusOK)
	})
	h := servedMedia(next, idx)
	send := func(method, target string) {
		t.Helper()
		h.ServeHTTP(httptest.NewRecorder(), httptest.NewRequest(method, target, nil))
	}

	send(http.MethodGet, "/media/itm_a/n1/seg0.ts")
	if !idx.recent("itm_a", "n1", time.Minute) {
		t.Fatal("the nonce artifact GET never touched the index")
	}
	send(http.MethodHead, "/media/itm_a/n1/index.m3u8")
	if !idx.recent("itm_a", "n1", time.Minute) {
		t.Fatal("the HEAD variant never touched the index")
	}
	send(http.MethodGet, "/media/itm_t/n2/t/seg5.ts")
	if !idx.recent("itm_t", "n2", time.Minute) {
		t.Fatal("the tail-segment subpath never touched its (item, nonce)")
	}
	send(http.MethodPost, "/media/itm_p/n3/seg0.ts")
	if idx.recent("itm_p", "n3", time.Minute) {
		t.Fatal("a non-GET/HEAD method touched the index")
	}

	send(http.MethodGet, "/media/itm_c/original")
	if idx.recent("itm_c", "original", time.Minute) {
		t.Fatal("the /original direct floor touched the index")
	}
	send(http.MethodGet, "/api/v1/items")
	if len(passed) != 6 {
		t.Fatalf("handler delegated %d requests, want all 6 (every path passes through): %v", len(passed), passed)
	}
}

// TestPlayingItems pins the live-session union: a fresh progress stamp or a
// fresh served read lands the item in the set, either signal alone is
// enough, window-stale progress stamps are excluded, and a nil served index
// degrades to the progress-only projection.
func TestPlayingItems(t *testing.T) {
	now := time.Now()
	fresh := now.Add(-time.Minute)
	stale := now.Add(-2 * playingWindow)
	recency := map[string]time.Time{
		"prog_only": fresh,
		"prog_both": fresh,
		"prog_dead": stale,
	}
	idx := newServedIndex()
	idx.touch("srv_only", "n1")
	idx.touch("srv_both", "n1")

	got := playingItems(recency, idx, now)
	for _, id := range []string{"prog_only", "prog_both", "srv_only", "srv_both"} {
		if !got[id] {
			t.Fatalf("playingItems = %v, want %q in the union", got, id)
		}
	}
	for _, id := range []string{"prog_dead", "srv_missing"} {
		if got[id] {
			t.Fatalf("playingItems = %v, want %q excluded", got, id)
		}
	}

	progressOnly := playingItems(recency, nil, now)
	if len(progressOnly) != 2 || !progressOnly["prog_only"] || !progressOnly["prog_both"] {
		t.Fatalf("playingItems(nil index) = %v, want the progress-only projection", progressOnly)
	}
}
